const createMeshStore = () => {
    let nodes: string[] = [];
    const addNode    = (id: string): void => { nodes = [...nodes, id]; };
    const removeNode = (id: string): void => { nodes = nodes.filter(n => n !== id); };
    return { addNode, removeNode };
};

